mapper.select:
SELECT o.ORDER_ID, o.ORDER_NO, o.ORDER_DATE, o.ORDER_STATUS, o.PAY_AMOUNT, o.CONFIRM_YN, o.CLAIM_STATUS, d.COURIER_NAME, d.COURIER_CODE, d.TRACKING_NO, b.BIZ_NAME, pay.TOSS_ORDER_ID AS ORDER_GROUP_ID FROM TB_ORDER o JOIN TB_BUSINESS b ON b.BIZ_NO = o.BIZ_NO LEFT JOIN TB_ORDER_DELIVERY d ON d.ORDER_ID = o.ORDER_ID LEFT JOIN TB_PAYMENT pay ON pay.ORDER_ID = o.ORDER_ID WHERE o.MEMBER_NO = #{memberNo}
AND ( o.ORDER_STATUS = 'CANCEL' OR o.CLAIM_STATUS = 'PENDING' OR EXISTS ( SELECT 1 FROM TB_ORDER_ITEM oi WHERE oi.ORDER_ID = o.ORDER_ID AND NVL(oi.RETURN_STATUS_CD, 'NONE') IN ('REQUESTED', 'RETURNING', 'DONE') ) )
AND o.ORDER_STATUS = 'SHIPPING' AND EXISTS ( SELECT 1 FROM TB_ORDER_ITEM oi WHERE oi.ORDER_ID = o.ORDER_ID AND NVL(oi.RETURN_STATUS_CD, 'NONE') <> 'DONE' )
AND o.ORDER_STATUS = 'DONE' AND EXISTS ( SELECT 1 FROM TB_ORDER_ITEM oi WHERE oi.ORDER_ID = o.ORDER_ID AND NVL(oi.RETURN_STATUS_CD, 'NONE') <> 'DONE' )
AND o.ORDER_STATUS = #{statusCd}
ORDER BY o.ORDER_ID DESC
